using System;
using System.Collections.Generic;
using System.IO;
using System.Threading;

public sealed partial class FaderConnection {
 static readonly object startupGate=new object();static readonly Dictionary<ulong,int> startupSnapshot=new Dictionary<ulong,int>();
 List<MixerParameter> startupReads;int startupCursor,startupRequestCount;double nextStartup;
 public int StartupRequestCount{get{lock(gate)return startupRequestCount;}}
 static bool IsStartupParameter(MixerParameter p){return p.Model==6&&((p.Area==2&&p.Element==1&&p.Index==0&&p.Channel<96)||(p.Area==4&&p.Element==31&&p.Index<3&&p.Channel<6));}
 static int FreezeStartupValue(MixerParameter spec,int value){if(!IsStartupParameter(spec))return value;lock(startupGate){int original;if(startupSnapshot.TryGetValue(spec.Key,out original))return original;startupSnapshot[spec.Key]=value;return value;}}
 void PollStartupMetadata(FaderReader output,double now){if(startupReads==null){startupReads=new List<MixerParameter>();for(int id=0;id<96;id++)startupReads.Add(Register(MixerParameter.InputSource(id)));for(int slot=0;slot<6;slot++)for(int field=0;field<3;field++)startupReads.Add(Register(MixerParameter.CardInfo(slot,field)));lock(startupGate)foreach(var p in startupReads){int value;if(startupSnapshot.TryGetValue(p.Key,out value))extra[p.Key]=new Scalar{Value=value,Time=DateTime.UtcNow};}}if(now<nextStartup||startupCursor>=startupReads.Count)return;for(int i=0;i<2&&startupCursor<startupReads.Count;i++){var p=startupReads[startupCursor++];bool cached;lock(startupGate)cached=startupSnapshot.ContainsKey(p.Key);if(!cached){output.ReadParameter(p,device);startupRequestCount++;}}nextStartup=now+10;}
 public static void TestStartupSnapshot(){var source=MixerParameter.InputSource(95);int prior;bool existed;lock(startupGate)existed=startupSnapshot.TryGetValue(source.Key,out prior);try{lock(startupGate)startupSnapshot.Remove(source.Key);if(FreezeStartupValue(source,25)!=25||FreezeStartupValue(source,57)!=25)throw new Exception("Source snapshot changed after startup");}finally{lock(startupGate){startupSnapshot.Remove(source.Key);if(existed)startupSnapshot[source.Key]=prior;}}}
 public static void VerifyStartupHardware(){using(var log=new StreamWriter(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"startup-source-test.txt"))){log.AutoFlush=true;using(var c=FeatureTests.Open()){Thread.Sleep(1800);for(int id=0;id<96;id++)if(!c.Channel(id).Source.HasValue)throw new Exception("Missing startup source "+id);for(int slot=0;slot<6;slot++)if(!c.Card(slot).Complete)throw new Exception("Missing startup card "+slot);int initial=c.StartupRequestCount;for(int bank=0;bank<4;bank++){c.SetMixerView(bank,-1);Thread.Sleep(200);}Thread.Sleep(5500);if(c.StartupRequestCount!=initial||initial!=114)throw new Exception("Startup sources were requested repeatedly");for(int id=0;id<96;id++)if(!c.Channel(id).Source.HasValue)throw new Exception("Startup source expired");log.WriteLine("PASS: 96 sources + 18 card fields read once; no repeat on bank changes or after five seconds.");}using(var c=FeatureTests.Open()){Thread.Sleep(1800);if(c.StartupRequestCount!=0||!c.Channel(24).Source.HasValue)throw new Exception("Reconnect reread the startup snapshot");log.WriteLine("PASS: reconnect reuses this app session's snapshot without rereading source metadata.");}}}
}
